//! 🧬️ Type changes move funded own Part21 values and retain declaration, derived and template positions.
use super::*;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_value::retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedCloneClose};
use std::mem::size_of;
type Declaration=catalog::IfcEntityDeclaration;
#[derive(Clone,Copy,Default)]enum Phase{#[default]Init,Attribute,Derived,Match,Build,Template,TemplateClose,Guid,GuidScan,Commit,Reconcile,Done}
pub(super)struct TypeChange{phase:Phase,part:usize,target:Option<&'static Declaration>,previous:Option<&'static Declaration>,old:Option<(String,Vec<V>)>,attribute:usize,match_index:usize,matched:Option<usize>,scan_part:usize,scan_attribute:usize,derived:bool,reconcile:bool,template:template::Template,next:Option<V>,displaced:Option<V>,retirement:RetainedCloneClose,guid:Option<String>,guid_row:usize,guid_part:usize,closing:bool}
impl Default for TypeChange{fn default()->Self{Self{phase:Default::default(),part:0,target:None,previous:None,old:None,attribute:0,match_index:0,matched:None,scan_part:0,scan_attribute:0,derived:false,reconcile:false,template:Default::default(),next:None,displaced:None,retirement:Default::default(),guid:None,guid_row:0,guid_part:0,closing:false}}}
fn error()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"Part21 type-change owner or declaration is missing")}
fn requested(event:&SnapshotEditEvent)->Option<(usize,&str)>{let SnapshotEditEvent::SetValue{path,value}=event else{return None};let mut fields=path.split('/').skip(1);if fields.next()!=Some("document")||fields.next()!=Some("instances"){return None;}fields.next()?.parse::<usize>().ok()?;if fields.next()!=Some("entities"){return None;}let part=fields.next()?.parse::<usize>().ok()?;let name=match(fields.next(),fields.next()){(None,None)=>requested_type(value)?,(Some("typeName"),None)=>if let DslValue::String(name)=value{name}else{return None},_=>return None};Some((part,name))}
impl TypeChange{
 pub(super)fn supports(event:&SnapshotEditEvent)->bool{requested(event).is_some()}
 fn attributes(&self,instance:&Part21Instance)->&'static[Attr]{let declaration=self.target.unwrap();if instance.entities.len()==1{&declaration.all_attributes}else{&declaration.attributes}}
 fn current_attribute(&self,instance:&Part21Instance)->Result<&'static Attr,ValueError>{if self.reconcile{let(name,_)=instance.entities.get(self.part).ok_or_else(error)?;let declaration=catalog::ifc2x3_catalog().entities.get(&name.to_ascii_uppercase()).ok_or_else(error)?;declaration.attributes.get(self.attribute).ok_or_else(error)}else{self.attributes(instance).get(self.attribute).ok_or_else(error)}}
 fn old_attributes(&self,instance:&Part21Instance)->&'static[Attr]{let declaration=self.previous.unwrap();if instance.entities.len()==1{&declaration.all_attributes}else{&declaration.attributes}}
 fn advance_attribute(&mut self){self.attribute+=1;self.phase=if self.reconcile{Phase::Reconcile}else{Phase::Attribute};self.scan_part=0;self.scan_attribute=0;self.matched=None;self.match_index=0;}
 pub(super)fn demands(&self,instance:&Part21Instance)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty()||self.displaced.is_some(){return self.retirement.next_owner_demands::<V>(self.displaced.is_some(),&None,64);}if matches!(self.phase,Phase::Template){return self.template.demands();}if matches!(self.phase,Phase::TemplateClose){return self.template.close_demands(64);}let capacity=if matches!(self.phase,Phase::Init){27*size_of::<V>()+256}else if matches!(self.phase,Phase::Guid){22}else{0};let _=instance;Ok(RetirementDemand{copy_bytes:6*size_of::<V>()+2*size_of::<(String,Vec<V>)>()+512,capacity_bytes:capacity,depth:1,..Default::default()})}
 pub(super)fn advance(&mut self,instance:&mut Part21Instance,event:&SnapshotEditEvent,snapshot:&Ifc2x3Snapshot,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{if cx.is_cancelled(){return Err(err("details-cancelled").into());}if cx.should_yield(){return Ok(false);}if matches!(self.phase,Phase::Done){return Ok(true);}let demand=self.demands(instance)?;let grant=cx.retained_grant();if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,demand){return Ok(false);}if !self.retirement.is_empty()||self.displaced.is_some(){let progress=if !self.retirement.is_empty(){self.retirement.step_granted(grant)?}else{self.retirement.begin_granted(&mut self.displaced,grant)?.ok_or_else(error)?};cx.consume_retained(progress.progress())?;cx.consume_fuel(1);return Ok(false);}let mut capacity=0;
 match self.phase{
 Phase::Init=>{let(part,name)=requested(event).ok_or_else(error)?;if name.len()>256||!name.is_ascii(){return Err(error().into());}let declaration=catalog::ifc2x3_catalog().entities.get(&name.to_ascii_uppercase()).ok_or_else(error)?;if declaration.abstract_entity&&instance.entities.len()==1{return Err(err("Abstract IFC2x3 entity requires a complex instance").into());}let old=instance.entities.get(part).ok_or_else(error)?;if old.0.len()>256{return Err(error().into());}let previous=catalog::ifc2x3_catalog().entities.get(&old.0.to_ascii_uppercase()).ok_or_else(error)?;let count=if instance.entities.len()==1{declaration.all_attributes.len()}else{declaration.attributes.len()};if count>27{return Err(error().into());}let mut args=Vec::new();args.try_reserve_exact(count).map_err(|_|err("Part21 target argument capacity allocation failed"))?;let name=declaration.name.clone();capacity=args.capacity()*size_of::<V>()+name.capacity();self.old=Some(std::mem::replace(&mut instance.entities[part],(name,args)));self.target=Some(declaration);self.previous=Some(previous);self.part=part;self.phase=Phase::Attribute;}
 Phase::Attribute=>{if self.attribute==self.attributes(instance).len(){if instance.entities.len()==1{self.phase=Phase::Done;}else{self.reconcile=true;self.part=0;self.attribute=0;self.phase=Phase::Reconcile;}}else{let attribute=self.current_attribute(instance)?;self.derived=attribute.derived;self.scan_part=0;self.scan_attribute=0;self.phase=Phase::Derived;}}
 Phase::Derived=>{let attribute=self.current_attribute(instance)?;if self.scan_part==instance.entities.len(){self.phase=if self.reconcile{Phase::Build}else{Phase::Match};self.match_index=0;self.matched=None;}else{let name=&instance.entities[self.scan_part].0;if name.len()>256{return Err(error().into());}let declaration=catalog::ifc2x3_catalog().entities.get(&name.to_ascii_uppercase()).ok_or_else(error)?;if let Some(other)=declaration.all_attributes.get(self.scan_attribute){self.derived|=other.derived&&other.declared_by==attribute.declared_by&&other.name==attribute.name;self.scan_attribute+=1;}else{self.scan_attribute=0;self.scan_part+=1;}}}
 Phase::Match=>{let attribute=self.current_attribute(instance)?;let previous=self.old_attributes(instance);if let Some(old)=previous.get(self.match_index){if old.name==attribute.name&&old.type_expr==attribute.type_expr{self.matched=Some(self.match_index);self.phase=Phase::Build;}self.match_index+=1;}else{self.phase=Phase::Build;}}
 Phase::Build=>{let attribute=self.current_attribute(instance)?;if self.reconcile{let value=&instance.entities[self.part].1[self.attribute];if self.derived{if !matches!(value,V::Derived){self.displaced=Some(std::mem::replace(&mut instance.entities[self.part].1[self.attribute],V::Derived));}self.advance_attribute();}else if !matches!(value,V::Derived){self.advance_attribute();}else if attribute.optional{instance.entities[self.part].1[self.attribute]=V::Unset;self.advance_attribute();}else{self.template.start(&attribute.type_expr)?;self.phase=Phase::Template;}}else if self.derived{self.next=Some(V::Derived);self.phase=Phase::Commit;}else if let Some(position)=self.matched.filter(|position|self.old.as_ref().unwrap().1.get(*position).is_some_and(|value|!matches!(value,V::Derived)&&(!matches!(value,V::Unset)||attribute.optional))){self.next=Some(std::mem::replace(&mut self.old.as_mut().unwrap().1[position],V::Unset));self.phase=Phase::Commit;}else if attribute.optional{self.next=Some(V::Unset);self.phase=Phase::Commit;}else if attribute.name=="GlobalId"{self.phase=Phase::Guid;}else{self.template.start(&attribute.type_expr)?;self.phase=Phase::Template;}}
 Phase::Template=>{if self.template.advance(snapshot,cx)?{self.next=Some(self.template.take()?.unwrap_or(V::Unset));self.template.begin_close();self.phase=Phase::TemplateClose;}return Ok(false);}
 Phase::TemplateClose=>{if self.template.terminal_is_empty(){self.template.reset()?;self.phase=Phase::Commit;}else{let progress=self.template.close_step(grant)?;cx.consume_retained(progress.progress())?;cx.consume_fuel(1);return Ok(false);}}
 Phase::Guid=>{let guid=identity::random_global_id(instance.id);capacity=guid.capacity();self.guid=Some(guid);self.guid_row=0;self.guid_part=0;self.phase=Phase::GuidScan;}
 Phase::GuidScan=>{if let Some(other)=snapshot.document.instances.get(self.guid_row){if let Some((_,args))=other.entities.get(self.guid_part){if args.first().is_some_and(|value|matches!(value,V::Str(value)if Some(value)==self.guid.as_ref())){self.displaced=self.guid.take().map(V::Str);self.phase=Phase::Guid;}else{self.guid_part+=1;}}else{self.guid_row+=1;self.guid_part=0;}}else{self.next=self.guid.take().map(V::Str);self.phase=Phase::Commit;}}
 Phase::Commit=>{let value=self.next.take().ok_or_else(error)?;if self.reconcile{self.displaced=Some(std::mem::replace(&mut instance.entities[self.part].1[self.attribute],value));}else{instance.entities[self.part].1.push(value);}self.advance_attribute();}
 Phase::Reconcile=>{if self.part==instance.entities.len(){self.phase=Phase::Done;}else{let(name,args)=&instance.entities[self.part];if name.len()>256{return Err(error().into());}let declaration=catalog::ifc2x3_catalog().entities.get(&name.to_ascii_uppercase()).ok_or_else(error)?;if self.attribute>=args.len().min(declaration.attributes.len()){self.part+=1;self.attribute=0;}else{self.derived=declaration.attributes[self.attribute].derived;self.scan_part=0;self.scan_attribute=0;self.phase=Phase::Derived;}}}
 Phase::Done=>return Ok(true),}
 cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,retained_capacity_bytes:capacity,..Default::default()})?;cx.consume_fuel(1);Ok(matches!(self.phase,Phase::Done))}
 pub(super)fn begin_close(&mut self){self.closing=true;self.template.begin_close();}
 pub(super)fn terminal_is_empty(&self)->bool{self.template.terminal_is_empty()&&self.old.is_none()&&self.next.is_none()&&self.displaced.is_none()&&self.guid.is_none()&&self.retirement.is_empty()}
 pub(super)fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.template.terminal_is_empty(){return self.template.close_demands(body);}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<V>(false,&None,body);}if self.old.is_some(){return self.retirement.next_owner_demands::<(String,Vec<V>)>(true,&None,body);}if self.next.is_some()||self.displaced.is_some(){return self.retirement.next_owner_demands::<V>(true,&None,body);}self.retirement.next_owner_demands::<String>(self.guid.is_some(),&None,body)}
 pub(super)fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(error());}if !self.template.terminal_is_empty(){return self.template.close_step(grant);}if !self.retirement.is_empty(){return self.retirement.step_granted(grant);}if self.old.is_some(){return self.retirement.begin_granted(&mut self.old,grant)?.ok_or_else(error);}for value in [&mut self.next,&mut self.displaced]{if value.is_some(){return self.retirement.begin_granted(value,grant)?.ok_or_else(error);}}if self.guid.is_some(){return self.retirement.begin_granted(&mut self.guid,grant)?.ok_or_else(error);}Ok(RetainedCloneStep::Complete(Default::default()))}
}
